async function init(){try{db=await new Promise((r,j)=>{const req=indexedDB.open('astral-collection',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>r(req.result);req.onerror=()=>j(req.error)});const saved=await new Promise((r,j)=>{const req=db.transaction('state').objectStore('state').get('characters');req.onsuccess=()=>r(req.result);req.onerror=j});chars=saved??structuredClone(samples)}catch{chars=structuredClone(samples);$('#saveStatus').textContent='저장 불가 · 현재 화면에서만 사용'}chars=chars.map(c=>Object.fromEntries(Object.entries(c).filter(([k])=>!['job','rarity','level','power','attack','defense','hp','speed','story'].includes(k))));chars=chars.map(c=>{const i=c.sample&&['selene','kael'].indexOf(c.id);return i!==false&&i>=0?{...c,...structuredClone(samples[i])}:c});chars=chars.map(c=>{const replacement=samples.find(s=>s.id===c.id);return replacement&&c.cutoutRevision!==2?{...c,image:replacement.image,original:replacement.original,cutoutRevision:2}:c});await save();renderRoster();if(chars.length)await select(chars[0].id,false);else empty();setMotion();}
