function edit(frame=false){const c=current();if(!c)return;const f=$('#editForm');for(const key of ['name','roman','quote','scale','x','y'])f.elements[key].value=key==='x'?0:c[key]??'';f.elements.bgColor.value=c.bgColor||'#b8def0';f.elements.accentColor.value=c.accentColor||'#ef507d';palettePreview();startElements(c);$('#framePreview').src=c.image;$('#frameSettings').open=frame;previewFrame();$('#editDialog').showModal()}function previewFrame(){const f=$('#editForm');$('#framePreview').style.setProperty('--scale',f.elements.scale.value/100);$('#framePreview').style.setProperty('--x',f.elements.x.value+'%');$('#framePreview').style.setProperty('--y',f.elements.y.value+'%');$('#scaleOut').textContent=f.elements.scale.value+'%'}$$('#editForm input[type=range]').forEach(e=>e.oninput=previewFrame);$('#framing').onclick=()=>edit(true);$('#editForm').onsubmit=async e=>{e.preventDefault();const c=current(),f=e.target;c.elements=structuredClone(elementDraft);for(const key of ['name','roman','quote','bgColor','accentColor'])c[key]=f.elements[key].value.trim();for(const key of ['scale','x','y'])c[key]=Number(f.elements[key].value);await save();$('#editDialog').close();renderRoster();select(c.id);};$('#delete').onclick=()=>$('#deleteDialog').showModal();$('#confirmDelete').onclick=async()=>{chars=chars.filter(c=>c.id!==selected);await save();$('#deleteDialog').close();$('#editDialog').close();chars=chars.map(c=>Object.fromEntries(Object.entries(c).filter(([k])=>!['job','rarity','level','power','attack','defense','hp','speed','story'].includes(k))));renderRoster();if(chars.length)select(chars[0].id);else empty()};
