function applyElementsBase(settings,root=document){for(const [key,selector,label,defaultText] of elementDefs){const el=root.querySelector(selector);if(!el)continue;const v=settings[key]||{};el.style.display=(v.hidden??['heading','top','note','tape','stamp','bottom','folio','issue','registration','crop1','crop2'].includes(key))?'none':'';el.style.borderWidth=v.strokeWidth===undefined?'':v.strokeWidth+'px';el.style.borderStyle=v.strokeWidth===undefined?'':'solid';el.style.borderColor=v.strokeColor||'';el.style.background=v.fillColor===undefined?'':v.fillColor;el.style.opacity=v.opacity===undefined?'':String(v.opacity/100);el.style.zIndex=v.layer===undefined?'':String(v.layer);el.style.rotate=(v.rotation||0)+'deg';el.style.translate=(v.x||0)+'vw '+(v.y||0)+'vh';el.style.scale=(v.size||100)/100;if(defaultText!==null){const priorImage=el.querySelector('img')?.src;el.innerHTML=originals.get(key)||'';if(priorImage&&el.querySelector('img'))el.querySelector('img').src=priorImage;if(v.text!==undefined){let target=key==='heading'?el.querySelector('span'):key==='note'?el.querySelector('b'):key==='crop1'||key==='crop2'?el.querySelector('span'):key==='top'||key==='bottom'?el.querySelector('span'):null;if(target)target.textContent=v.text;else if(key==='issue'){el.replaceChildren(document.createTextNode(v.text));const symbol=document.createElement('b');symbol.textContent='✳';el.append(symbol)}else el.textContent=v.text}}}}
