$('.stage').addEventListener('pointerdown',e=>{if(e.target.closest('button,[contenteditable=true]'))return;const el=e.target.closest('[data-edit-key]');if(!el||isLocked(el.dataset.editKey))return;liveKey=el.dataset.editKey;if(!canvasMode){toggleCanvas(true);const panel=$('#inspector');const er=el.getBoundingClientRect();const pr=panel.getBoundingClientRect();if(er.right>pr.left&&er.left<pr.right&&er.bottom>pr.top&&er.top<pr.bottom){panel.style.left=er.left>innerWidth/2?'12px':Math.max(12,innerWidth-pr.width-12)+'px';panel.style.right='auto';panel.style.top='80px';panel.style.bottom='auto'}};remember();readLive();const v=liveValue();dragState={el,startX:e.clientX,startY:e.clientY,x:v.x||0,y:v.y||0};/* capture begins after movement */});
$('.stage').addEventListener('pointermove',e=>{if(!dragState)return;const c=current(),d=dragState;if(Math.hypot(e.clientX-d.startX,e.clientY-d.startY)<3)return;if(!d.el.hasPointerCapture(e.pointerId))d.el.setPointerCapture(e.pointerId);let x=d.x+(e.clientX-d.startX)/innerWidth*100,y=d.y+(e.clientY-d.startY)/innerHeight*100;if(liveKey==='character'){const r=$('#character').getBoundingClientRect();x=d.x+(e.clientX-d.startX)/r.width*100;y=d.y+(e.clientY-d.startY)/r.height*100;x=0;c.x=0;c.y=y;for(const id of ['character','silhouette']){$('#'+id).style.setProperty('--x',x+'%');$('#'+id).style.setProperty('--y',y+'%')}}else{c.elements??={};c.elements[liveKey]={...liveValue(),x,y};d.el.style.translate=x+'vw '+y+'vh'}});
function endDrag(){if(dragState){dragState=null;readLive();saveLive()}}$('.stage').addEventListener('pointerup',endDrag);$('.stage').addEventListener('pointercancel',endDrag);

const editHistory=[],redoHistory=[];
function remember(){redoHistory.length=0;if($('#liveRedo'))$('#liveRedo').disabled=true;const c=current();if(!c)return;const json=JSON.stringify(c);if(editHistory.at(-1)?.json!==json)editHistory.push({id:c.id,json});if(editHistory.length>40)editHistory.shift();$('#liveUndo').disabled=!editHistory.length}
$('#liveUndo').onclick=async()=>{let prev=editHistory.pop();while(prev&&prev.id===current()?.id&&prev.json===JSON.stringify(current()))prev=editHistory.pop();if(!prev){$('#liveUndo').disabled=true;return;}const i=chars.findIndex(c=>c.id===prev.id);if(i<0)return;redoHistory.push({id:chars[i].id,json:JSON.stringify(chars[i])});$('#liveRedo').disabled=false;chars[i]=JSON.parse(prev.json);await select(prev.id,false);readLive();saveLive();$('#liveUndo').disabled=!editHistory.length};
