function positionLive(x,y){const c=current();if(!c||isLocked())return;if(liveKey==='character'){c.x=0;c.y=y;for(const id of ['character','silhouette'])$('#'+id).style.setProperty('--y',y+'%')}else{c.elements??={};c.elements[liveKey]={...liveValue(),x,y};const el=$(liveDefs.find(d=>d[0]===liveKey)[1]);el.style.translate=x+'vw '+y+'vh'}readLive();saveLive()}
