document.addEventListener('keydown',e=>{if(!canvasMode||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='Escape'){toggleCanvas(false);return}if((e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();$(e.shiftKey||e.key.toLowerCase()==='y'?'#liveRedo':'#liveUndo').click();return}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();remember();const v=liveValue(),step=e.shiftKey?1:.1;positionLive((v.x||0)+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),(v.y||0)+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0))});

// Floating inspector stays within the viewport when dragged or resized.
let panelDrag=null;
const inspector=$('#inspector'),panelHead=$('.inspector-head');
panelHead.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;e.preventDefault();const r=inspector.getBoundingClientRect();panelDrag={x:e.clientX,y:e.clientY,left:r.left,top:r.top};inspector.style.width=r.width+'px';inspector.style.left=r.left+'px';inspector.style.top=r.top+'px';inspector.style.right='auto';inspector.style.bottom='auto';panelHead.setPointerCapture(e.pointerId)});
