let draggedLayer=null;
function renderLayers(){
 const host=$('#layerList');if(!host||!current())return;
 const c=current();host.replaceChildren();
 const rows=liveDefs.map((def,index)=>{const el=$(def[1]);return {def,el,index,z:baseLayer(el)}}).sort((a,b)=>b.z-a.z||b.index-a.index);
 for(const {def,el} of rows){
  const [key,,label]=def;if($('#layerSearch')?.value&&!label.toLowerCase().includes($('#layerSearch').value.toLowerCase()))continue;const hidden=getComputedStyle(el).display==='none';
  const row=document.createElement('div');row.className='layer-row'+(liveKey===key?' selected':'');row.draggable=!isLocked(key);row.dataset.key=key;
  const eye=document.createElement('button');eye.className='layer-eye';eye.textContent=hidden?'○':'◉';eye.title=hidden?'레이어 표시':'레이어 숨기기';eye.setAttribute('aria-label',label+' '+(hidden?'표시':'숨기기'));eye.onclick=()=>{if(isLocked(key)){toast('잠금을 먼저 해제하세요.');return}remember();if(key==='character'){c.characterHidden=!c.characterHidden;el.style.display=c.characterHidden?'none':''}else{c.elements??={};c.elements[key]={...(c.elements[key]||{}),hidden:!hidden};applyElements(c.elements)}renderLayers();saveLive()};
  const pick=document.createElement('button');pick.className='layer-pick';pick.setAttribute('aria-label',label+' 레이어 선택');
  const thumb=document.createElement('span');thumb.className='layer-thumb';
  const art=el.querySelector('img');if(art){const img=document.createElement('img');img.src=art.src;img.alt='';thumb.append(img)}else if(key==='wash'){thumb.style.background='linear-gradient(0deg,#fff,transparent)'}else if(key==='background'){thumb.style.background=c.bgColor||'#b8def0'}else{thumb.textContent=(el.textContent||'◇').trim().slice(0,10)}
  const text=document.createElement('span');text.className='layer-name';text.textContent=label;const sub=document.createElement('small');sub.textContent=(c.elements?.[key]?.opacity??100)+'% · '+(hidden?'숨김':'표준');text.append(sub);pick.append(thumb,text);pick.onclick=()=>{liveKey=key;readLive()};
  const lock=document.createElement('button');lock.className='layer-lock';lock.textContent=isLocked(key)?'🔒':'🔓';lock.setAttribute('aria-label',label+(isLocked(key)?' 잠금 해제':' 잠금'));lock.title=isLocked(key)?'잠금 해제':'레이어 잠금';lock.onclick=()=>{remember();c.elements??={};c.elements[key]={...(c.elements[key]||{}),locked:!isLocked(key)};readLive();saveLive()};row.append(eye,pick,lock);host.append(row);
  row.ondragstart=e=>{draggedLayer=key;e.dataTransfer.setData('text/plain',key);e.dataTransfer.effectAllowed='move'};
  row.ondragover=e=>{e.preventDefault();row.classList.add('drop-target')};row.ondragleave=()=>row.classList.remove('drop-target');
  row.ondrop=e=>{e.preventDefault();if(!draggedLayer||draggedLayer===key||isLocked(draggedLayer)||isLocked(key))return;remember();const order=rows.map(r=>r.def[0]).filter(k=>k!==draggedLayer);order.splice(order.indexOf(key),0,draggedLayer);c.elements??={};order.forEach((k,i)=>{const z=order.length-i;c.elements[k]={...(c.elements[k]||{}),layer:z};if(k==='character')c.characterLayer=z});applyElements(c.elements);$('#artContainer').style.zIndex=c.characterLayer??4;liveKey=draggedLayer;draggedLayer=null;readLive();saveLive()};
 }
}

function applyBackground(c){const a=c.bgColor||'#b8def0',b=c.bgSecond||'#ffffff',mode=c.bgMode||'solid';$('.stage').style.background=mode==='linear'?`linear-gradient(${c.bgAngle??135}deg,${a},${b})`:mode==='radial'?`radial-gradient(ellipse at center,${a},${b})`:a}
for(const id of ['bgMode','bgSecond','bgAngle'])$('#'+id).oninput=()=>{const c=current();if(!c)return;remember();c.bgMode=$('#bgMode').value;c.bgSecond=$('#bgSecond').value;c.bgAngle=+$('#bgAngle').value;applyBackground(c);saveLive()};
// Keep the layer list and properties in separate columns, with independent scroll.
const layerColumn=document.createElement('div');layerColumn.className='layer-column';const propertyColumn=document.createElement('div');propertyColumn.className='property-column';const editorBody=document.createElement('div');editorBody.className='editor-body';
const list=$('#layerList');layerColumn.append(list);const children=[...inspector.children];for(const el of children){if(!el.matches('.inspector-head,p'))propertyColumn.append(el)}editorBody.append(layerColumn,propertyColumn);inspector.append(editorBody);

function readPaint(v,def){const disabled=['character','ghost','crop1','crop2'].includes(liveKey);$('#paintControls').disabled=disabled;const style=getComputedStyle($(def[1]));$('#strokeWidth').value=v.strokeWidth??(parseFloat(style.borderTopWidth)||0);$('#strokeColor').value=v.strokeColor||'#ffffff';$('#fillColor').value=v.fillColor&&v.fillColor!=='transparent'?v.fillColor:'#ffffff';$('#fillClear').checked=v.fillColor==='transparent';}
for(const id of ['strokeWidth','strokeColor','fillColor','fillClear'])$('#'+id).oninput=()=>{const c=current();if(!c||isLocked())return;c.elements??={};const v=c.elements[liveKey]??={};if(id==='strokeWidth')v.strokeWidth=Math.max(0,Math.min(24,Number($('#strokeWidth').value)||0));if(id==='strokeColor')v.strokeColor=$('#strokeColor').value;if(id==='fillColor'){v.fillColor=$('#fillColor').value;$('#fillClear').checked=false}if(id==='fillClear')v.fillColor=$('#fillClear').checked?'transparent':$('#fillColor').value;applyElements(c.elements);markSelection();saveLive()};

function textLeaves(el){return [...el.querySelectorAll('*')].filter(n=>!n.children.length&&n.tagName!=='IMG'&&n.textContent.trim()).concat(!el.children.length&&el.textContent.trim()?[el]:[])}
function applyElements(settings,root=document){applyElementsBase(settings,root);for(const [key,selector] of elementDefs){const el=root.querySelector(selector);if(!el)continue;const leaves=textLeaves(el);for(const [index,text] of Object.entries(settings[key]?.inlineTexts||{})){if(leaves[index])leaves[index].textContent=text}}}
let editingText=null;
function beginTextEdit(e){
 if(e.target.closest('button'))return;const box=e.target.closest('[data-edit-key]');if(!box||isLocked(box.dataset.editKey)||box.dataset.editKey==='character')return;
 let leaf=e.target;
 if(leaf.children.length){const direct=[...leaf.childNodes].find(n=>n.nodeType===3&&n.textContent.trim());if(direct){const span=document.createElement('span');span.textContent=direct.textContent;direct.replaceWith(span);leaf=span}else leaf=textLeaves(leaf)[0]}
 if(!leaf||!leaf.textContent.trim())return;
 e.preventDefault();remember();liveKey=box.dataset.editKey;toggleCanvas(true);editingText=leaf;
 const index=textLeaves(box).indexOf(leaf);leaf.contentEditable='true';leaf.spellcheck=false;leaf.focus();
 const range=document.createRange();range.selectNodeContents(leaf);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);
 const before=leaf.textContent;
 const finish=(cancel=false)=>{if(editingText!==leaf)return;editingText=null;leaf.contentEditable='false';const text=cancel?before:leaf.innerText;leaf.textContent=text;const c=current();if(!cancel){if(liveKey==='title'){c.roman=text;$('#largeName').dataset.title=text;$('#epithet').textContent=text}else if(liveKey==='caption'&&leaf.id==='quote'){c.quote=text}else{c.elements??={};const v=c.elements[liveKey]??={};v.inlineTexts??={};v.inlineTexts[index]=text}save();saveLive()}readLive();leaf.removeEventListener('blur',blur);leaf.removeEventListener('keydown',key)};
 const blur=()=>finish(),key=e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();finish(true)}else if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();finish()}};
 leaf.addEventListener('blur',blur);leaf.addEventListener('keydown',key);
}
$('.stage').addEventListener('dblclick',e=>{if(!editingText)beginTextEdit(e)});
let lastTextTap={time:0,target:null};
$('.stage').addEventListener('pointerdown',e=>{const now=performance.now();if(lastTextTap.target===e.target&&now-lastTextTap.time<450&&!editingText){dragState=null;beginTextEdit(e);lastTextTap={time:0,target:null}}else lastTextTap={time:now,target:e.target}},true);
const transformBox=document.createElement('div');transformBox.id='transformBox';transformBox.hidden=true;document.body.append(transformBox);
for(const pos of ['nw','n','ne','e','se','s','sw','w']){const h=document.createElement('button');h.className='transform-handle '+pos;h.dataset.handle=pos;h.setAttribute('aria-label',pos+' 크기 조절');transformBox.append(h)}
let resizeDrag=null;
transformBox.addEventListener('pointerdown',e=>{const handle=e.target.dataset.handle;if(!handle||isLocked())return;e.preventDefault();e.stopPropagation();remember();const el=$(liveDefs.find(d=>d[0]===liveKey)[1]);const r=(liveKey==='character'?$('#character'):el).getBoundingClientRect();resizeDrag={x:e.clientX,y:e.clientY,size:liveValue().size||100,width:r.width,height:r.height,handle};e.target.setPointerCapture(e.pointerId)});
transformBox.addEventListener('pointermove',e=>{if(!resizeDrag)return;const d=resizeDrag;let delta;if(['n','s'].includes(d.handle))delta=(e.clientY-d.y)/d.height*(d.handle==='n'?-1:1);else delta=(e.clientX-d.x)/d.width*(d.handle.includes('w')?-1:1);const size=Math.max(25,Math.min(350,Math.round(d.size*(1+delta))));$('#liveSize').value=size;updateLive()});
for(const event of ['pointerup','pointercancel'])transformBox.addEventListener(event,()=>{resizeDrag=null;readLive()});
function refreshTransform(){if(canvasMode&&!editingText&&!isLocked()){const def=liveDefs.find(d=>d[0]===liveKey),el=liveKey==='character'?$('#character'):$(def[1]);const r=el.getBoundingClientRect();transformBox.hidden=getComputedStyle(el).display==='none'||r.width===0;Object.assign(transformBox.style,{left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px'});}else transformBox.hidden=true;requestAnimationFrame(refreshTransform)}requestAnimationFrame(refreshTransform);
transformBox.addEventListener('dblclick',e=>{resizeDrag=null;const el=$(liveDefs.find(d=>d[0]===liveKey)[1]);beginTextEdit({target:el,preventDefault:()=>e.preventDefault()})});

function baseLayer(el){const selected=el.classList.contains("canvas-selected");el.classList.remove("canvas-selected");const z=parseInt(getComputedStyle(el).zIndex)||0;if(selected)el.classList.add("canvas-selected");return z}

function isLocked(key=liveKey){return !!current()?.elements?.[key]?.locked}
function lockControls(){for(const id of ['liveSize','liveRotation','liveX','liveY','liveText','liveLayer','liveOpacity','liveVisible','liveReset']){const el=$('#'+id);el.disabled=isLocked()||(['liveX','liveOpacity','liveLayer','liveVisible'].includes(id)&&liveKey==='character')||(id==='liveText'&&liveDefs.find(d=>d[0]===liveKey)[3]===null&&!['title','caption'].includes(liveKey))}if(isLocked())$('#paintControls').disabled=true;$('#liveStatus').textContent=isLocked()?'잠긴 레이어 · 목록의 잠금을 해제해 편집하세요.':'변경 내용은 자동 저장됩니다.'}

$('#liveRedo').onclick=async()=>{const next=redoHistory.pop();if(!next)return;const i=chars.findIndex(c=>c.id===next.id);if(i<0)return;editHistory.push({id:chars[i].id,json:JSON.stringify(chars[i])});chars[i]=JSON.parse(next.json);await select(next.id,false);readLive();saveLive();$('#liveRedo').disabled=!redoHistory.length;$('#liveUndo').disabled=false};
const search=document.createElement('input');search.id='layerSearch';search.type='search';search.placeholder='레이어 이름으로 찾기';search.setAttribute('aria-label','레이어 검색');layerColumn.prepend(search);search.oninput=renderLayers;
$('#collapsePanel').onclick=()=>{const collapsed=inspector.classList.toggle('collapsed');$('#collapsePanel').textContent=collapsed?'펼치기':'접기';$('#collapsePanel').setAttribute('aria-expanded',String(!collapsed))};
const selectionLabel=document.createElement('div');selectionLabel.id='selectionLabel';propertyColumn.prepend(selectionLabel);
const originalReadLive=readLive;readLive=function(){originalReadLive();selectionLabel.textContent=liveDefs.find(d=>d[0]===liveKey)?.[2]||'요소 선택';};
const resetPanel=document.createElement('button');resetPanel.id='resetPanelPosition';resetPanel.textContent='패널 위치 복원';resetPanel.onclick=()=>{for(const prop of ['left','top','right','bottom','width'])inspector.style.removeProperty(prop);inspector.classList.remove('collapsed');$('#collapsePanel').textContent='접기';$('#collapsePanel').setAttribute('aria-expanded','true')};propertyColumn.append(resetPanel);

// A self-contained poster: no account, storage, or editor dependencies.
const downloadHTML=document.createElement('button');downloadHTML.id='downloadHTML';downloadHTML.className='download-html';downloadHTML.textContent='↓ HTML 다운로드';downloadHTML.title='현재 캐릭터의 완성 화면을 HTML 파일로 저장';$('#add').before(downloadHTML);
downloadHTML.onclick=async()=>{
 if(!current())return;
 downloadHTML.disabled=true;downloadHTML.textContent='파일 만드는 중…';
 try{
  if(editingText)editingText.blur();
  const stage=$('.stage').cloneNode(true);
  stage.querySelectorAll('button,.art-tools,.stage-controls').forEach(el=>el.remove());
  stage.querySelectorAll('[data-edit-key]').forEach(el=>{el.classList.remove('canvas-selected','canvas-target','is-locked');el.removeAttribute('data-edit-key')});
  stage.querySelectorAll('[contenteditable]').forEach(el=>el.removeAttribute('contenteditable'));
  const cache=new Map();
  async function inline(url){if(url.startsWith('data:'))return url;if(!cache.has(url))cache.set(url,(async()=>{const response=await fetch(url);if(!response.ok)throw Error('이미지 읽기 실패');return dataURL(await response.blob())})());return cache.get(url)}
  await Promise.all([...stage.querySelectorAll('img')].map(async img=>{img.src=await inline(img.src);img.removeAttribute('srcset')}));
  const response=await fetch(document.querySelector('link[rel="stylesheet"]').href);if(!response.ok)throw Error('스타일 읽기 실패');let css=await response.text();
  const imports=[...css.matchAll(/@import\s+url\(['"]?([^'"\)]+)['"]?\)\s*;/g)];
  for(const entry of imports){let fontCSS='';try{const res=await fetch(entry[1]);if(res.ok){fontCSS=await res.text();const urls=[...new Set([...fontCSS.matchAll(/url\(([^)]+)\)/g)].map(m=>m[1].replace(/['"]/g,'')))];for(const url of urls)fontCSS=fontCSS.split(url).join(await inline(url))}}catch{fontCSS=''}css=css.replace(entry[0],fontCSS)}
  const rootStyle=document.documentElement.getAttribute('style')||'';
  const doc=document.implementation.createHTMLDocument(current().name+' — 캐릭터 포스터');doc.documentElement.lang='ko';doc.documentElement.setAttribute('style',rootStyle);
  const meta=doc.createElement('meta');meta.name='viewport';meta.content='width=device-width,initial-scale=1';doc.head.append(meta);
  const style=doc.createElement('style');style.textContent=css+'\nhtml,body{margin:0;width:100%;height:100%;overflow:hidden}body{display:block!important}.stage{position:relative!important;width:100vw!important;height:100dvh!important;min-height:0!important;margin:0!important;border:0!important}.poster-edit,.character-nav,.art-actions{display:none!important}';doc.head.append(style);
  doc.body.append(stage);if(!motion)doc.body.classList.add('no-motion');
  const blob=new Blob(['<!doctype html>\n'+doc.documentElement.outerHTML],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(current().name||'character').replace(/[\\/:*?"<>|]/g,'_')+'-poster.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('현재 캐릭터의 포스터를 HTML로 저장했어요.');
 }catch(error){console.error(error);toast('파일을 만들지 못했어요. 이미지 연결을 확인하고 다시 시도해 주세요.')}
 finally{downloadHTML.disabled=false;downloadHTML.textContent='↓ HTML 다운로드'}
};
